INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA10_NOT_2006_01:LEY_NOTARIADO:51','mayalex_normativos','03_NOTARIAL','Están obligados a enviar los protocolos y/ o las fotocopias de los protocolos a la Contraloría del Notariado:

1) Los herederos o representantes legítimos de los Notarios que fallecieren;

2) Los Notarios que se ausenten de la República para domiciliarse fuera de ella, debiendo en este caso, a menos de urgencia imprevista, hacer la remisión a más tardar quince (15) días antes de su partida, y;

3) Los Notarios a quienes se decrete la suspensión e inhabilitación, dentro de los diez (10) días inmediatos a la fecha de haber quedado firme la resolución correspondiente.','51','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":51,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"6216571f43572c088422603dbb8158497d692384f2a086b21e3889b3dd54c632","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a51","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','51','6216571f43572c088422603dbb8158497d692384f2a086b21e3889b3dd54c632','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:52','mayalex_normativos','03_NOTARIAL','Cuando se pierda o inutilice en todo o en parte un protocolo o en su caso las fotocopias autorizadas del protocolo, el Notario dará cuenta inmediatamente a la Contraloría del Notariado para que instruya averiguación sobre el paradero o causa de la inutilización, así también respecto de la culpa que haya tenido el Notario y la responsabilidad de terceras personas.

Los Jueces de Paz letrados tienen las mismas obligaciones e iguales responsabilidades que los Notarios en la guarda o conservación de los protocolos.

Los Jueces de Paz, Agentes Diplomáticos y Consulares acreditados en el extranjero, al ser cesanteados en sus cargos, entregarán por inventario a sus sucesores el protocolo en que estén actuando.

El Reglamento Especial que emita la Corte Suprema de Justicia determinará el procedimiento y demás aspectos relacionados con la pérdida, extravío, inutilización y reposición del protocolo.','52','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":52,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"7a9b1b5455166d8fd55204aa4b6e6a7b7d39a601dca33949c6a4d843501f597c","ubicacion":["SECCIÓN NOVENA","PÉRDIDA, EXTRAVÍO, INUTILIZACIÓN Y REPOSICIÓN DEL","PROTOCOLO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a52","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','52','7a9b1b5455166d8fd55204aa4b6e6a7b7d39a601dca33949c6a4d843501f597c','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:53','mayalex_normativos','03_NOTARIAL','Los actos no contenciosos establecidos en el Código de Procedimientos Civiles y en otras leyes, pueden ser conocidos, tramitados y resueltos por los Notarios cuando medie consentimiento expreso y unánime de los interesados.

Los interesados pueden elegir libremente el trámite notarial o el judicial según lo estimen conveniente.

Escogida una vía no puede abandonarse para acudir a la otra, tampoco pueden emplearse simultánea o sucesivamente.

Es prohibido al Notario intervenir en asuntos no contenciosos cuando haya participado en los mismos como Abogado o haya participado en la autorización del acto o contrato de que se trate.','53','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":53,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"a840fbd2b007e8c33e444264e4d647eda7d9989ae0b0f3e743cf864e0bd31d7f","ubicacion":["CAPITULO IV","LA COMPETENCIA NOTARIAL EN ACTOS NO CONTENCIOSOS","SECCIÓN PRIMERA","DISPOSICIONES GENERALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a53","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','53','a840fbd2b007e8c33e444264e4d647eda7d9989ae0b0f3e743cf864e0bd31d7f','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:54','mayalex_normativos','03_NOTARIAL','Todo trámite debe iniciarse a instancia de parte interesada o por sus representantes o apoderados legales.

El mismo debe consignar la suma, designación del Notario, el nombre del o los solicitantes o sus representantes o apoderados con sus generales de ley, motivo de la solicitud, el derecho que le asiste, el fundamento legal, la petición, lugar y fecha y suscripción de la misma.','54','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":54,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"4ec02bd569d041731170eec0022fe2e7f6cd122672ccf8d14de21262b35cc7e1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a54","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','54','4ec02bd569d041731170eec0022fe2e7f6cd122672ccf8d14de21262b35cc7e1','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:55','mayalex_normativos','03_NOTARIAL','El Notario debe formar un expediente con las actuaciones de todo asunto no contencioso que se someta a su conocimiento y decisión. Asimismo debe hacer constar en Instrumento su resolución final, y el testimonio que se extienda al interesado tendrá el mismo valor que las certificaciones de las resoluciones judiciales dictadas en asuntos de la misma naturaleza.','55','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":55,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"893bf4a04fc26080460fe665a0e12e141788a62f37a2ace2c8dcc320de09fb06","ubicacion":["SECCIÓN SEGUNDA","ACTUACIÓN NOTARIAL EN ASUNTOS NO CONTENCIOSOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a55","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','55','893bf4a04fc26080460fe665a0e12e141788a62f37a2ace2c8dcc320de09fb06','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:56','mayalex_normativos','03_NOTARIAL','La actuación notarial en los asuntos no contenciosos están sujetos a lo dispuesto en el Código de Procedimientos Civiles, la presente Ley y demás leyes del país. En esta clase de asuntos el Notario no puede expedir copias parciales, o transcribir de él solamente una parte, cuando la parte omitida afecte a terceros.

El incumplimiento de esta disposición vicia de nulidad el testimonio y además, acarrea responsabilidad para el Notario que la infrinja.','56','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":56,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"63e70da25b23c7b31309a6006e8912d3aa11af7c240a6b6b16ffbfb0951649c7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a56","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','56','63e70da25b23c7b31309a6006e8912d3aa11af7c240a6b6b16ffbfb0951649c7','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:57','mayalex_normativos','03_NOTARIAL','En los casos en que específicamente lo disponga la Ley, es obligatorio oír al Ministerio Público antes de dictar cualquier resolución, bajo pena de nulidad de lo actuado. Dicha opinión deberá verterla dentro de un plazo no mayor de diez (10) días.','57','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":57,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"ce6c4fea404e233838a7493bfd40cc8c18a1f85d3b691c163b62eee995beffb6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a57","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','57','ce6c4fea404e233838a7493bfd40cc8c18a1f85d3b691c163b62eee995beffb6','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:58','mayalex_normativos','03_NOTARIAL','Los Notarios por medio de oficio pueden requerir de la autoridad competente la colaboración que sea necesaria, a fin de obtener los datos e informes que sean indispensables para la tramitación de los expedientes. Cuando injustificadamente no le fuere proporcionada la colaboración, después de haber sido requerida por dos (2) veces, transcurridos tres (3) días, pueden los Notarios acudir ante el Juez competente quien apremiará al requerido a prestar la colaboración solicitada, sin perjuicio de su responsabilidad de conformidad con la Ley.','58','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":58,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"2359734935c5308044c94e6e5671a7d32559c6880daf884633b185e11b72f433","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a58","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','58','2359734935c5308044c94e6e5671a7d32559c6880daf884633b185e11b72f433','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:59','mayalex_normativos','03_NOTARIAL','Los asuntos no contenciosos que pueden conocer los Notarios, además de los previstos en otras leyes, son los siguientes:

1) Rectificación de inscripciones en el Registro Civil;
2) Patrimonio familiar;
3) Habilitación para comparecer en juicio;
4) Emancipación voluntaria;
5) Habilitación de edad;
6) Información ad-perpetuam;
7) Divorcio por mutuo consentimiento;
8) Inventarios solemnes;

9) La separación de hecho;
10) Conciliación y arbitraje;
11) Ejecución de garantías;
12) Autorización para contraer segundas y ulteriores nupcias;
13) Autorización para enajenar bienes de menores;
14) Deslinde y amojonamiento;
15) Permisos de operación de comerciantes y autorización de sus libros;
16) Celebración de matrimonios;
17) Calificación de edad;
18) Cesación de comunidad; y,
19) Partición de bienes.','59','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":59,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"2a55c0489a2aac3574a714a10e81430a405140b6e097a8a2feb3e87d329a39d0","ubicacion":["SECCIÓN TERCERA","LOS ASUNTOS NO CONTENCIOSOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a59","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','59','2a55c0489a2aac3574a714a10e81430a405140b6e097a8a2feb3e87d329a39d0','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:60','mayalex_normativos','03_NOTARIAL','Las partes pueden acordar en los contratos someterse al procedimiento de ejecución de garantías prendarías e hipotecarias ante Notario, en cuyo caso, debe establecerse el precio base del inmueble dado en garantía y la forma del requerimiento, observándose el procedimiento establecido en la presente Ley.','60','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":60,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"b0680c6a0443fe351506e243a6a05d66def1c3beb113b60f5474e41b5a0e47bb","ubicacion":["CAPÍTULO V","EJECUCIÓN DE GARANTÍAS","SECCIÓN ÚNICA","REGLAS GENERALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a60","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','60','b0680c6a0443fe351506e243a6a05d66def1c3beb113b60f5474e41b5a0e47bb','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:61','mayalex_normativos','03_NOTARIAL','Cuando se constate que la obligación consta en título ejecutivo y es actualmente exigible, el Notario debe requerir al deudor para que cumpla con la obligación contraída en el término de veinticuatro (24) horas. En el mismo acto del requerimiento debe notificársele:

1) La obligación pendiente y el monto de la misma;

2) El nombre del titular, el lugar donde pueda pagarse o el nombre del establecimiento bancario y número de cuenta bancaria en la que puede consignar el valor;

3) El día, lugar y hora en la que se llevará a cabo la venta en pública subasta del bien dado en garantía conforme al precio base establecido en el contrato o pacto posterior, lo cual se efectuará dentro del término de tres (3) días previa publicación de un aviso en uno de los diarios de mayor circulación del país; y,

4) La expresión de ante quien debe efectuarse el pago o consignación, que puede hacerse en cualquier tiempo antes del plazo señalado para el evento.','61','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":61,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"752ee3aeae446cb5d1fbe9e9d57c1909b588e235e5ce57e09a789fe5ca1bd36a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a61","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','61','752ee3aeae446cb5d1fbe9e9d57c1909b588e235e5ce57e09a789fe5ca1bd36a','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:62','mayalex_normativos','03_NOTARIAL','Cuando esté autorizado el empleo de una dirección física para practicar requerimientos y notificaciones para la venta por el acreedor o la venta extrajudicial por Notario y no se encuentren en esa dirección la persona o personas a las que se deba dirigir, del requerimiento o la notificación debe fijarse una copia en la entrada del lugar debiendo también entregársele copia a cualquier persona que allí se encuentre y a dos (2) de los vecinos del lugar quienes actuarán como testigos del acto. Además, puede realizarse una filmación en video de estas actuaciones.','62','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":62,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"3534d71532cee1f9a18ea576bfccbdbc3a541997a7cc47ed82079dccab85b81f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a62","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','62','3534d71532cee1f9a18ea576bfccbdbc3a541997a7cc47ed82079dccab85b81f','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:63','mayalex_normativos','03_NOTARIAL','El acta donde conste el requerimiento o notificación por Notario debe inscribirse en el registro público en el mismo asiento en el que se haya inscrito la garantía.','63','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":63,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"91b72ecc351a4c43f83b99f084399973dce145d1aa100e5702070780c9642a2f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a63","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','63','91b72ecc351a4c43f83b99f084399973dce145d1aa100e5702070780c9642a2f','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:64','mayalex_normativos','03_NOTARIAL','El registro de la notificación o requerimiento como anotación en el asiento donde se encuentre inscrito el bien o el acto o contrato tendrá el mismo valor de los embargos decretados judicialmente.','64','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":64,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"9e512c7827a3a9506c22f5b2459c9d153ee4268fbac26cd35557eab8a7b30d30","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a64","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','64','9e512c7827a3a9506c22f5b2459c9d153ee4268fbac26cd35557eab8a7b30d30','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:65','mayalex_normativos','03_NOTARIAL','La venta debe hacerse en pública subasta a favor de quien ofrezca el mejor precio.

El acreedor puede participar en la subasta ofertando el valor de su crédito o un monto superior.

En caso de que nadie participe en la subasta se adjudicará el bien a favor del acreedor sin necesidad de que éste oferte su crédito. En los casos en que el valor del bien rematado no cubra el pago total de la obligación quedará a salvo el derecho del acreedor de perseguir otros bienes del deudor, debiendo constar en el acta correspondiente.

De todo lo actuado debe levantarse el acta correspondiente. Esta acta servirá de título traslaticio del dominio sobre la garantía, debiendo inscribirse la misma.','65','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":65,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"01486183b0d94a9df3fd1b4290263fab602f753446557e6312c3253c477b02ce","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a65","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','65','01486183b0d94a9df3fd1b4290263fab602f753446557e6312c3253c477b02ce','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:66','mayalex_normativos','03_NOTARIAL','Las normas para determinar la prioridad y prelación de derechos de los acreedores sobre las garantías serán determinadas por la legislación de derecho privado que corresponda.','66','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":66,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"b167da6c89204924fab78caf8a861d8ffc7ca621d4288fa5a02be238fa63bd70","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a66","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','66','b167da6c89204924fab78caf8a861d8ffc7ca621d4288fa5a02be238fa63bd70','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:67','mayalex_normativos','03_NOTARIAL','Cuando existan otros acreedores garantizados por los bienes que se ejecutarán, el acreedor interesado en su ejecución debe notificarles a los otros acreedores.','67','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":67,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"5140e1cc85f773f14c56bf4bd1b456b947994d92ebcbed2aff1cae51deec5a9c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a67","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','67','5140e1cc85f773f14c56bf4bd1b456b947994d92ebcbed2aff1cae51deec5a9c','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:68','mayalex_normativos','03_NOTARIAL','Cuando estos otros acreedores hayan autorizado el empleo de una dirección física para practicar requerimientos y notificaciones, el acreedor interesado puede notificarles en esa dirección.

Si no se encontraren en la misma, debe fijarse una copia de la notificación en la entrada del lugar, debiendo también entregársele copia a cualquier persona que allí se encuentre y a dos (2) de los vecinos del lugar quienes servirán de testigos de este acto.

Esta notificación debe inscribirse en el registro público donde se encuentre inscrito el bien dado en garantía.','68','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":68,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"7e4e87556c6df1bd860072cac38d001b8c4d773fc4b6cbca86fa1d192769b6d4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a68","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','68','7e4e87556c6df1bd860072cac38d001b8c4d773fc4b6cbca86fa1d192769b6d4','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:69','mayalex_normativos','03_NOTARIAL','Cuando existan varios acreedores éstos pueden ponerse de acuerdo sobre la forma en que distribuirán los resultados de la venta por acreedor o de la venta extrajudicial por Notario.','69','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":69,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"5dce2688d2280e63a7692f7f2c197f6a4ea2cf2e1f823e3e1a379c1ce9652bbd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a69","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','69','5dce2688d2280e63a7692f7f2c197f6a4ea2cf2e1f823e3e1a379c1ce9652bbd','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:70','mayalex_normativos','03_NOTARIAL','Cuando no se pueda notificar a los otros acreedores que tengan derechos sobre la misma garantía o éstos no lleguen a un acuerdo después de ser notificados, debe solicitarse autorización especial del juez del domicilio donde se encuentren los bienes para seguir adelante con el proceso de ejecución.

Para el otorgamiento de esta autorización el juez puede solicitar que se rinda caución para garantizar los derechos de los otros acreedores. Esta notificación debe inscribirse en el registro público.','70','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":70,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"a616ed39641801d9531568b4bf271174ff98e675ff902455333e4c3510e4199c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a70","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','70','a616ed39641801d9531568b4bf271174ff98e675ff902455333e4c3510e4199c','OLA10_NOT_2006_01',now()),
('OLA10_NOT_2006_01:LEY_NOTARIADO:71','mayalex_normativos','03_NOTARIAL','El Notario ante quien se hubiese constituido una garantía no puede participar en la ejecución de la misma.','71','Código del Notariado de Honduras (Decreto No. 353-2005)','{"norm_id":"HN:LEY_NOTARIADO","instrumento_id":"LEY_NOTARIADO","ingest_batch":"OLA10_NOT_2006_01","ola":"OLA10","ordinal":71,"decreto":"353-2005","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «Codigo-del-Notariado.pdf», con notas al pie del D.77-2006 y el texto del D.77-2006 anexo.","pdf_sha256":"efe971f876fa9b9bc23fad82fc3d669aab864f48dab6169a85f202c1dd2513c8","article_sha256":"9db1862d5df36b5b785e81b790cf7019ba0c93b24e33744962bdb64c1f370239","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:codigo_notariado_2005_a71","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_NOTARIADO','71','9db1862d5df36b5b785e81b790cf7019ba0c93b24e33744962bdb64c1f370239','OLA10_NOT_2006_01',now()),
