DO $do$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA10_NOT_2006_01' AND metadata->>'norm_id' = 'HN:LEY_NOTARIADO'
    AND instrumento_id = 'LEY_NOTARIADO' AND jurisdiccion = 'HN' AND encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido AND revision_pendiente = true AND es_norma_vigente IS NULL;
  IF n <> 94 THEN RAISE EXCEPTION 'post-insert prod (ocultas, hash correcto): % filas (esperadas 94)', n; END IF;
END $do$;
COMMIT;
